$_MODULE['<{pshubspot}prestashop>dashboard_b3ccbdae546c549af7d54c8534fc5d0f'] = 'Im Juni 2021 ist die Konfiguration zum Modulpreis kostenlos. Überlassen Sie es uns, wir verbinden PrestaSyncro für Sie! Diese Konfiguration beinhaltet die Installation des Moduls, die Verbindung mit dem HubSpot-Konto, die Synchronisation ab dem gewünschten Datum und die Erstellung einer Automatisierung zur Wiederherstellung verlassener Warenkörbe.';
$_MODULE['<{pshubspot}prestashop>dashboard_ddcf50c29294d4414f3f7c1bbc892cb5'] = 'Ressourcen';
$_MODULE['<{pshubspot}prestashop>dashboard_1aaa497abb2f34e28d42efd32f8c9cc6'] = 'Hier finden Sie Ressourcen, um Ihre Prestashop-Integration mit HubSpot zu nutzen. Wir stellen Ihnen Anleitungen und Vorlagen zur Verfügung, um schnell vordefinierte Kampagnen zu starten und in wenigen Minuten werden Sie verlassene Warenkörbe, Gutscheinaktionen, Geburtstagsgrüße usw. wiederherstellen.';
