$_MODULE['<{pshubspot}prestashop>start_28b23a27ab5e1a4bcce23ddedebd5293'] = 'Mit dieser PrestaShop-Integration in HubSpot können Sie alle Ihre PrestaShop-Kontakte und / oder Kunden automatisch mit der HubSpot-Plattform synchronisieren.';
$_MODULE['<{pshubspot}prestashop>start_527d858ae39f2b16f210ee47bfa10779'] = 'Sobald die Integration konfiguriert ist, können Sie:';
$_MODULE['<{pshubspot}prestashop>start_0f7942e103ec6359e031d037d4f0db22'] = 'Erstellen und versenden Sie ganz einfach Mailings, um den Umsatz zu steigern (aufgegebene Warenkörbe, Werbeaktionen, Cross-Produkte, Geburtstage usw.).';
$_MODULE['<{pshubspot}prestashop>start_79b7210e72e8ae585620d6c8a5458228'] = 'E-Commerce-Berichte innerhalb von Hubspot im Detail.';
$_MODULE['<{pshubspot}prestashop>start_4f0d06ed7ddbbaefb28e4cb8fa3fefd3'] = 'Browserverlauf und Kundenbestellungen (Seitenaufrufe, generierte Warenkörbe, Bestellverlauf, gekaufte Produkte, unter anderem) und Kunden, Bestellungen in ihren verschiedenen Phasen werden in wenigen Minuten synchronisiert. Sie können den verlassenen Warenkorb für die gewünschte Zeit konfigurieren generiert werden.';
$_MODULE['<{pshubspot}prestashop>start_226aa7a9c5f3c2308dca6f5a394d7f01'] = 'Sie können Gutscheinaktionen einfacher verwalten. Sie haben alle Ihre Prestashop-Produkte in Hubspot für Mailing, Landing Page und andere Anwendungen.';
$_MODULE['<{pshubspot}prestashop>start_84f24bf8bfca28e983b00a98804d6879'] = 'Wenn Sie beim Kauf dieses Moduls einen Lizenzschlüssel erhalten haben, können Sie diesen hier eingeben.';
